from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
Mt_1 = Motor(Port.F, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.D, Direction.CLOCKWISE)
Att_MTR = Motor(Port.A, Direction.CLOCKWISE)
Att_MTR_2 = Motor(Port.B, Direction.CLOCKWISE)
drive_base_2 = DriveBase(Mt_1, motor_2, 86, 132)


# The main program starts here.
drive_base_2.use_gyro(True)
drive_base_2.straight(200)
drive_base_2.turn(-50)
drive_base_2.straight(300)
drive_base_2.turn(-90)
drive_base_2.straight(205)
drive_base_2.turn(40)
drive_base_2.straight(130)
drive_base_2.turn(100)
drive_base_2.settings(straight_speed=100)
drive_base_2.straight(100)
drive_base_2.settings(straight_speed=400)
drive_base_2.straight(-120)
drive_base_2.turn(-80)
drive_base_2.straight(-700)
